<?php
namespace Tivoli\Service;
use Tivoli\Infrastructure\HrVault;
use Tivoli\Security\PermissionDenied;
use RuntimeException;
final class HrPrivateService {
    private readonly HrVault $vault;private readonly string $directory;
    public function __construct(private readonly AccessService $access,array $config,string $root){$this->vault=new HrVault($config['hr_key'] ?? '');$this->directory=$root.'/storage/'.(getenv('TIVOLI_TEST_MODE')==='1'?'hr-documents-test':'hr-documents');}
    private function permit(int $actor,string $permission):void {$this->access->requirePrivilege($actor,$permission);}
    private function text(array $in,string $key,int $max,bool $required=false):string {$value=$in[$key] ?? '';if(!is_string($value))throw new RuntimeException('Invalid '.$key.'.');$value=trim($value);if(($required&&$value==='')||!mb_check_encoding($value,'UTF-8')||mb_strlen($value)>$max||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f]/',$value))throw new RuntimeException('Invalid or overly long '.$key.'.');return $value;}
    private function staff(int $id,bool $write=false):array {$staff=$this->access->repo->run('SELECT id,status FROM hr_staff WHERE id=?'.($write?' FOR UPDATE':''),[$id])->fetch();if(!$staff)throw new RuntimeException('Staff record not found.');if($write&&$staff['status']==='exited')throw new RuntimeException('Exited staff records are retained; new salary/documents cannot be added.');return $staff;}
    private function audit(int $actor,string $action,string $type,?int $id,array $details=[]):void {$staffId=$type==='staff'?$id:($type==='hr_document'?(int)$this->access->repo->run('SELECT staff_id FROM hr_documents WHERE id=?',[$id])->fetchColumn():0);if($staffId)$this->access->repo->run('INSERT INTO hr_history(staff_id,actor_id,action,reason_html,details) VALUES(?,?,?,?,?)',[$staffId,$actor,'hr.'.$action,'',json_encode($details,JSON_THROW_ON_ERROR)]);$this->access->audit($actor,'hr.'.$action,$type,$id?(string)$id:null,'succeeded',$details);}
    public function catalogue(int $actor):array {return $this->access->transaction(function()use($actor){$u=$this->access->repo->user($actor);$permissions=$this->access->repo->privileges($actor);if(!$u||!$u['active']||!array_intersect(['hr.settings','hr.salary','hr.documents'],$permissions))throw new PermissionDenied('You cannot access private HR lists.');$result=['document'=>[],'momo'=>[],'bank'=>[]];foreach($this->access->repo->run('SELECT * FROM hr_catalogue ORDER BY name,id')->fetchAll() as $row)$result[$row['group_name']][]=$row;$this->audit($actor,'catalogue_viewed','hr_settings',null);return $result;});}
    public function saveCatalogue(int $actor,array $in):int {
        return $this->access->transaction(function()use($actor,$in){$this->permit($actor,'hr.settings');$r=$this->access->repo;if(!$r->isAdmin($actor))throw new PermissionDenied('Only an administrator may change HR settings.');$group=$this->text($in,'group_name',20,true);if(!in_array($group,['document','momo','bank']))throw new RuntimeException('Choose a valid HR list.');$name=$this->text($in,'name',80,true);$reason=$this->text($in,'reason',500,true);$active=$in['active'] ?? '';if(!in_array($active,['0','1'],true))throw new RuntimeException('Choose a valid entry status.');$id=(int)($in['id'] ?? 0);$before=[];
        if($id){$before=$r->run('SELECT * FROM hr_catalogue WHERE id=? FOR UPDATE',[$id])->fetch();if(!$before||$before['group_name']!==$group||(int)$before['version']!==(int)($in['version'] ?? 0))throw new RuntimeException('This settings entry changed. Reload before saving.');$r->run('UPDATE hr_catalogue SET name=?,active=?,version=version+1 WHERE id=?',[$name,$active,$id]);}
        else{$r->run('INSERT INTO hr_catalogue(group_name,name,active) VALUES(?,?,?)',[$group,$name,$active]);$id=(int)$r->db->lastInsertId();}
        $this->audit($actor,'catalogue_saved','hr_catalogue',$id,['group'=>$group,'reason'=>$reason,'before'=>array_intersect_key($before,array_flip(['name','active','version'])),'after'=>['name'=>$name,'active'=>$active]]);return $id;});
    }
    public function documents(int $actor,int $staffId):array {return $this->access->transaction(function()use($actor,$staffId){$this->permit($actor,'hr.documents');$this->staff($staffId);$rows=$this->access->repo->run('SELECT d.id,d.filename,d.mime,d.size_bytes,d.type_id,d.created_by,d.created_at,c.name AS type_name,c.active AS type_active FROM hr_documents d JOIN hr_catalogue c ON c.id=d.type_id WHERE d.staff_id=? ORDER BY d.id DESC',[$staffId])->fetchAll();$this->audit($actor,'documents_viewed','staff',$staffId);return $rows;});}
    public function upload(int $actor,int $staffId,int $typeId,array $file):int {
        $this->permit($actor,'hr.documents');$path=null;
        try{
            if(($file['error'] ?? UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_string($file['name'] ?? null)||!is_string($file['tmp_name'] ?? null)||!is_uploaded_file($file['tmp_name']))throw new RuntimeException('Choose a valid uploaded file.');
            $size=filesize($file['tmp_name']);if($size===false||$size<1||$size>5*1024*1024)throw new RuntimeException('Document must be between 1 byte and 5 MB.');
            $name=str_replace('\\','/',(string)($file['name'] ?? ''));$name=basename($name);$name=preg_replace('/[^\pL\pN ._()-]/u','_',$name) ?? '';if($name===''||mb_strlen($name)>190)throw new RuntimeException('Choose a shorter document filename.');
            $mime=(new \finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$extension=strtolower(pathinfo($name,PATHINFO_EXTENSION));$types=['pdf'=>'application/pdf','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png'];
            if(!isset($types[$extension])||$types[$extension]!==$mime)throw new RuntimeException('Only matching PDF, JPG or PNG files are accepted.');
            if($mime!=='application/pdf'&&!@getimagesize($file['tmp_name']))throw new RuntimeException('Invalid image document.');
            $plain=file_get_contents($file['tmp_name']);if($plain===false||strlen($plain)!==$size)throw new RuntimeException('Could not read the document.');
            $key=bin2hex(random_bytes(32));if(!is_dir($this->directory)&&!mkdir($this->directory,0700,true)&&!is_dir($this->directory))throw new RuntimeException('Private document storage is unavailable.');
            $path=$this->directory.'/'.$key.'.enc';$stream=fopen($path,'xb');if(!$stream)throw new RuntimeException('Could not create private document.');$cipher=$this->vault->seal($plain,'document:'.$staffId.':'.$key);try{if(fwrite($stream,$cipher)!==strlen($cipher)||!fflush($stream))throw new RuntimeException('Could not save private document.');}finally{fclose($stream);} @chmod($path,0600);
            $result=$this->access->transaction(function()use($actor,$staffId,$typeId,$name,$mime,$size,$key,$plain){$this->permit($actor,'hr.documents');$this->staff($staffId,true);$r=$this->access->repo;if(!$r->run("SELECT id FROM hr_catalogue WHERE id=? AND group_name='document' AND active=1 FOR UPDATE",[$typeId])->fetchColumn())throw new RuntimeException('Choose an active document type.');$hash=hash('sha256',$plain);$prior=$r->run('SELECT id FROM hr_documents WHERE staff_id=? AND type_id=? AND sha256=?',[$staffId,$typeId,$hash])->fetchColumn();if($prior)return -(int)$prior;$r->run('INSERT INTO hr_documents(staff_id,type_id,storage_key,filename,mime,size_bytes,sha256,created_by) VALUES(?,?,?,?,?,?,?,?)',[$staffId,$typeId,$key,$name,$mime,$size,$hash,$actor]);$id=(int)$r->db->lastInsertId();$this->audit($actor,'document_uploaded','hr_document',$id,['staff_id'=>$staffId,'type_id'=>$typeId,'size_bytes'=>$size]);return $id;});
            if($result<0){unlink($path);return -$result;}return $result;
        }catch(\Throwable $e){if($path&&is_file($path))unlink($path);throw $e;}
    }
    public function download(int $actor,int $documentId):array {return $this->access->transaction(function()use($actor,$documentId){$this->permit($actor,'hr.documents');$row=$this->access->repo->run('SELECT * FROM hr_documents WHERE id=?',[$documentId])->fetch();if(!$row||!preg_match('/^[a-f0-9]{64}$/D',$row['storage_key']))throw new RuntimeException('Document unavailable.');$path=$this->directory.'/'.$row['storage_key'].'.enc';if(!is_file($path)||is_link($path))throw new RuntimeException('Document unavailable.');$cipher=file_get_contents($path);if($cipher===false)throw new RuntimeException('Document unavailable.');$bytes=$this->vault->open($cipher,'document:'.$row['staff_id'].':'.$row['storage_key']);if(strlen($bytes)!==(int)$row['size_bytes']||!hash_equals($row['sha256'],hash('sha256',$bytes)))throw new RuntimeException('Document integrity verification failed.');$this->audit($actor,'document_downloaded','hr_document',$documentId,['staff_id'=>(int)$row['staff_id'],'type_id'=>(int)$row['type_id']]);unset($row['storage_key'],$row['sha256']);return [...$row,'bytes'=>$bytes];});}
    public function salary(int $actor,int $staffId):?array {return $this->access->transaction(function()use($actor,$staffId){$this->permit($actor,'hr.salary');$this->staff($staffId);$r=$this->access->repo;$row=$r->run('SELECT * FROM hr_salary_versions WHERE staff_id=? ORDER BY id DESC LIMIT 1',[$staffId])->fetch();$this->audit($actor,'salary_viewed','staff',$staffId);if(!$row)return null;$data=json_decode($this->vault->open($row['payload'],'salary:'.$staffId),true,512,JSON_THROW_ON_ERROR);unset($row['payload'],$row['reason']);$history=$r->run('SELECT id,effective_date,created_at,created_by FROM hr_salary_versions WHERE staff_id=? ORDER BY id DESC',[$staffId])->fetchAll();return [...$data,...$row,'history'=>$history];});}
    public function saveSalary(int $actor,int $staffId,array $in):int {return $this->access->transaction(function()use($actor,$staffId,$in){$this->permit($actor,'hr.salary');$this->staff($staffId,true);$r=$this->access->repo;$prior=$r->run('SELECT * FROM hr_salary_versions WHERE staff_id=? ORDER BY id DESC LIMIT 1 FOR UPDATE',[$staffId])->fetch();$expected=filter_var($in['expected_salary_id'] ?? '',FILTER_VALIDATE_INT);if($expected===false||$expected!==(int)($prior['id'] ?? 0))throw new RuntimeException('Salary details changed. Reload before saving.');
        $data=['amount'=>\Tivoli\Domain\Money\ExpenseAmount::parse($this->text($in,'amount',20,true))];$data['frequency']=$this->text($in,'frequency',20,true);if(!in_array($data['frequency'],['monthly','fortnightly','weekly','daily']))throw new RuntimeException('Choose a valid pay frequency.');$data['effective_date']=$this->text($in,'effective_date',10,true);$date=\DateTimeImmutable::createFromFormat('!Y-m-d',$data['effective_date']);if(!$date||$date->format('Y-m-d')!==$data['effective_date'])throw new RuntimeException('Enter a valid effective date.');$data['preferred']=$this->text($in,'preferred',10,true);if((new FinanceService($this->access))->installed()&&$data['preferred']!=='momo')throw new RuntimeException('Salary payments now use MoMo only. Previous revisions remain retained.');if(!in_array($data['preferred'],['momo','bank','cash']))throw new RuntimeException('Choose a valid payment method.');if(($in['confirmed'] ?? '')!=='1')throw new RuntimeException('Confirm payment details with the staff member.');
        foreach(['momo_name'=>120,'momo_number'=>40,'branch'=>120,'bank_holder'=>120,'bank_number'=>40,'account_type'=>20,'routing_code'=>40,'notes'=>1000,'reason'=>500] as $key=>$max)$data[$key]=$this->text($in,$key,$max,$key==='reason');if(!in_array($data['account_type'],['savings','current','other']))throw new RuntimeException('Choose a valid account type.');
        foreach(['momo_id'=>'momo','bank_id'=>'bank'] as $key=>$group){$raw=$in[$key] ?? '';$id=$raw===''?null:filter_var($raw,FILTER_VALIDATE_INT);if($id===false||($id!==null&&$id<1))throw new RuntimeException('Choose a valid payment provider.');$data[$key]=$id;if($id){$entry=$r->run('SELECT * FROM hr_catalogue WHERE id=? AND group_name=? FOR UPDATE',[$id,$group])->fetch();if(!$entry||(!$entry['active']&&(int)($prior[$key] ?? 0)!==$id))throw new RuntimeException('Choose an active payment provider.');}}
        if($data['preferred']==='momo'&&(!$data['momo_id']||!$data['momo_name']||!preg_match('/^[+0-9 ()-]{6,40}$/D',$data['momo_number'])))throw new RuntimeException('Provide the MoMo provider, registered name and valid number.');
        if($data['preferred']==='bank'&&(!$data['bank_id']||!$data['bank_holder']||!preg_match('/^[a-zA-Z0-9 -]{4,40}$/D',$data['bank_number'])))throw new RuntimeException('Provide bank, account holder and valid account number.');
        $r->run('INSERT INTO hr_salary_versions(staff_id,preferred,momo_id,bank_id,effective_date,payload,reason,created_by) VALUES(?,?,?,?,?,?,?,?)',[$staffId,$data['preferred'],$data['momo_id'],$data['bank_id'],$data['effective_date'],$this->vault->seal(json_encode($data,JSON_THROW_ON_ERROR),'salary:'.$staffId),'Restricted reason encrypted in payload',$actor]);$id=(int)$r->db->lastInsertId();$this->audit($actor,'salary_updated','staff',$staffId,['revision_id'=>$id,'previous_revision_id'=>(int)($prior['id'] ?? 0),'effective_date'=>$data['effective_date'],'preferred'=>$data['preferred'],'sensitive_values_excluded'=>true]);return $id;
    });}
}
